function draftSettings(spreadsheetId, sheetId, site) {
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    !Number.isInteger(sheetId) ||
    sheetId < 0
  ) {
    throw new Error("Set the spreadsheet ID and numeric tab ID.");
  }
  const host =
    typeof site === "string"
      ? site.match(
          /^https:\/\/([a-z0-9]+(?:[.-][a-z0-9]+)*\.[a-z]{2,})(?:\/[a-z0-9_-]+)*\/?$/i,
        )?.[1]
      : undefined;
  if (!host || ["example.com", "example.org"].includes(host.toLowerCase())) {
    throw new Error("Set the WordPress HTTPS site URL with its domain and optional subdirectory.");
  }
  return { spreadsheetId, sheetId, wp: site.replace(/\/$/, "") + "/wp-json/wp/v2" };
}

function sheetRange(settings, row, startColumnIndex = 0, endColumnIndex = 6) {
  return {
    gridRange: {
      sheetId: settings.sheetId,
      startColumnIndex,
      endColumnIndex,
      ...(row === undefined ? {} : { startRowIndex: row, endRowIndex: row + 1 }),
    },
  };
}

export default ({ spreadsheetId, sheetId, site }) => {
  const settings = draftSettings(spreadsheetId, sheetId, site);
  return { settings, spreadsheetId, filter: [sheetRange(settings)] };
};

