  return {
    model: "deepseek-v4-pro",
    thinking: { type: "enabled" },
    max_tokens: 8192,
    messages: [{ role: "user", content: prompt }],
    stream: false,
  };
}

function articleRequest(plan) {
  return deepseekBody(
    "Write an SEO-friendly article based on the topic below. Include a roughly 120-word introduction, " +
      "four or five logically related sections without chapter numbers, and a roughly 120-word conclusion. " +
      "Return only HTML. Use only p, h2, h3, ul, ol, li, strong, b, em, and i elements without attributes. " +
      "Write in the language of the topic. Topic:\n" +
      plan.prompt,
  );
}

export default ({ plans, previous, finished, settings }) => {
  const index = previous ?? 0;
  const plan = plans[index] ?? null;
  return {
    index: index + 1,
    plan: plan ?? {},
    more: !!plan,
    body: plan && articleRequest(plan),
    filter: plan ? [sheetRange(settings, plan.row)] : [],
    results: finished ?? [],
  };
};

