function contentText(response) {
  const choice = response?.choices?.[0];
  const text = choice?.message?.content;
  if (typeof text !== "string" || !text.trim() || choice.finish_reason !== "stop") {
    throw new Error("DeepSeek returned no complete content.");
  }
  return text.trim();
}

function preparedArticle(response) {
  const article = contentText(response);
  const tags = /<\/?(?:p|h2|h3|ul|ol|li|strong|b|em|i)>/gi;
  if (
    article.length > 45000 ||
    !/<p>/i.test(article) ||
    /[<>]|\x60\x60\x60/.test(article.replace(tags, ""))
  ) {
    throw new Error("DeepSeek did not return the allowed article HTML.");
  }
  return article;
}

function deepseekBody(prompt) {
  return {
    model: "deepseek-v4-pro",
    thinking: { type: "enabled" },
    max_tokens: 8192,
    messages: [{ role: "user", content: prompt }],
    stream: false,
  };
}

function titleRequest(article) {
  return deepseekBody(
    "Return only a search-friendly title of up to 60 characters for this article. Use its keywords and language. " +
      "Use letters, numbers, spaces, colons or commas. Do not include HTML, quotes or formatting. Article:\n" +
      article,
  );
}

export default ({ response }) => {
  const article = preparedArticle(response);
  return { article, body: titleRequest(article) };
};

