function preparedTitle(response) {
  const title = contentText(response);
  if ([...title].length > 60 || !/^[\p{L}\p{M}\p{N} :,]+$/u.test(title)) {
    throw new Error("DeepSeek did not return a plain title of up to 60 characters.");
  }
  return title;
}

function imageRequest(title) {
  return {
    model: "gpt-image-2.5-flare",
    output_format: "png",
    size: "1792x1024",
    quality: "high",
    n: 1,
    prompt:
      "A realistic editorial photograph used as a cover for a blog post, with an 85 mm photography look. Article title: " +
      title,
  };
}

export default ({ response }) => {
  const title = preparedTitle(response);
  return { title, body: imageRequest(title) };
};

