function coverPng(response, decode) {
  const encoded = response?.data?.length === 1 ? response.data[0]?.b64_json : undefined;
  if (
    typeof encoded !== "string" ||
    encoded.length > 10000000 ||
    encoded.length % 4 ||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(encoded) ||
    (response.output_format && response.output_format !== "png")
  ) {
    throw new Error("OpenAI did not return one embedded PNG.");
  }
  const bytes = decode(encoded);
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  if (bytes.length < 45 || !signature.every((byte, i) => bytes[i] === byte))
    throw new Error("Invalid cover PNG.");
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let hasImageData = false;
  for (let offset = 8; offset + 12 <= bytes.length;) {
    const length = view.getUint32(offset);
    const end = offset + 12 + length;
    if (end > bytes.length) break;
    const chunk = String.fromCharCode(...bytes.subarray(offset + 4, offset + 8));
    if (
      offset === 8 &&
      (chunk !== "IHDR" ||
        length !== 13 ||
        view.getUint32(offset + 8) !== 1792 ||
        view.getUint32(offset + 12) !== 1024)
    )
      break;
    if (chunk === "IDAT" && length > 0) hasImageData = true;
    if (chunk === "IEND") {
      if (hasImageData && length === 0 && end === bytes.length) return { encoded, bytes };
      break;
    }
    offset = end;
  }
  throw new Error("Invalid or incomplete 1792 × 1024 cover PNG.");
}

function decodeResponseJson(bytes) {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  const parts = [];
  for (let offset = 0; offset < bytes.length; offset += 131072) {
    parts.push(decoder.decode(bytes.subarray(offset, offset + 131072), { stream: true }));
  }
  parts.push(decoder.decode());
  return JSON.parse(parts.join(""));
}

function decodeArtifactBase64(encoded) {
  const padding = encoded.endsWith("==") ? 2 : Number(encoded.endsWith("="));
  const bytes = new Uint8Array((encoded.length / 4) * 3 - padding);
  let destination = 0;
  for (let offset = 0; offset < encoded.length; offset += 131072) {
    const chunk = atob(encoded.slice(offset, offset + 131072));
    for (let index = 0; index < chunk.length; index++)
      bytes[destination++] = chunk.charCodeAt(index);
  }
  return bytes;
}

function endpointForDraft(settings, slug) {
  return (
    settings.wp +
    "/posts?context=edit&slug=" +
    encodeURIComponent(slug) +
    "&status[]=draft&status[]=pending&status[]=publish&status[]=private&status[]=future"
  );
}

export default async ({ response, plan, settings }, context) => {
  if (response.mediaType !== "application/json")
    throw new Error("OpenAI did not return image JSON.");
  const body = decodeResponseJson(await context.artifact.open(response));
  const { bytes } = coverPng(body, decodeArtifactBase64);
  return {
    file: await context.artifact.put(bytes, {
      name: plan.slug + "-cover.png",
      mediaType: "image/png",
    }),
    url: endpointForDraft(settings, plan.slug),
  };
};

