  const ranges = response?.valueRanges;
  const [values] = ranges?.length === 1 ? [ranges[0]?.valueRange?.values] : [];
  if (!Array.isArray(values)) throw new Error("Google Sheets did not return the configured range.");
  return values;
}

function checkRow(response, plan, claimed) {
  const rows = draftRows(response);
  const [date, prompt, title, postId, ideaId, state] = rows[0] ?? [];
  if (
    rows.length !== 1 ||
    ideaId !== plan.ideaId ||
    prompt !== plan.prompt ||
    date ||
    title ||
    postId ||
    (state ?? "") !== (claimed ? "IN PROGRESS" : "")
  ) {
    throw new Error(
      "The planned idea row changed. Review its IDEA ID and WordPress records before running again.",
    );
  }
}

function sheetRange(settings, row, startColumnIndex = 0, endColumnIndex = 6) {
  return {
    gridRange: {
      sheetId: settings.sheetId,
      startColumnIndex,
      endColumnIndex,
      ...(row === undefined ? {} : { startRowIndex: row, endRowIndex: row + 1 }),
    },
  };
}

function sheetWrite(settings, plan, fields) {
  return {
    valueInputOption: "RAW",
    data: fields.map(([column, value]) => ({
      dataFilter: sheetRange(settings, plan.row, column, column + 1),
      majorDimension: "ROWS",
      values: [[value]],
    })),
  };
}

function checkSheetWrite(response, settings, fields) {
  if (response?.spreadsheetId !== settings.spreadsheetId || response.totalUpdatedCells !== fields) {
    throw new Error(
      "Google Sheets did not confirm the requested write. Review the row before running again.",
    );
  }
}

function noDraft(response) {
  if (!Array.isArray(response) || response.length)
    throw new Error(
      "An existing WordPress post matches this IDEA ID or the lookup failed. Review it before running again.",
    );
}

export default ({ existing, valueRanges, plan, settings }) => {
  noDraft(existing);
  checkRow({ valueRanges }, plan, false);
  return { data: sheetWrite(settings, plan, [[5, "IN PROGRESS"]]).data };
};

