function draftReceipt(post, plan) {
  if (
    !Number.isSafeInteger(post?.id) ||
    post.id < 1 ||
    post.status !== "draft" ||
    post.slug !== plan.slug
  ) {
    throw new Error(
      "WordPress did not confirm the expected draft. Review the row before retrying.",
    );
  }
  return post.id;
}

export default ({ post, settings, plan }) => {
  const postId = draftReceipt(post, plan);
  return {
    postId,
    url:
      settings.wp + "/media?post=" + postId + "&slug=" + encodeURIComponent(plan.slug + "-cover"),
    disposition: 'attachment; filename="' + plan.slug + '-cover.png"',
  };
};

