function imageReceipt(media, postId, plan) {
  if (
    !Number.isSafeInteger(media?.id) ||
    media.id < 1 ||
    media.post !== postId ||
    media.slug !== plan.slug + "-cover" ||
    media.mime_type !== "image/png"
  ) {
    throw new Error("WordPress did not confirm this draft’s PNG attachment.");
  }
  return media.id;
}

export default ({ media, postId, settings, plan }) => {
  const mediaId = imageReceipt(media, postId, plan);
  return {
    url: settings.wp + "/posts/" + postId,
    mediaId,
    body: { status: "draft", featured_media: mediaId },
  };
};

